def f(s):
    if s == "":
        return ""
    return f(s[1:]) + s[0]

print(f("HTL"))

def summe(liste, acc=0):
    if not liste:
        return acc
    return summe(liste[1:],
                 acc + liste[0])

def countdown(n):
    if n == 0:
        print("Los!")
    else:
        print(n)
        countdown(n)

countdown(3)

def potenz(x, n):
    if n == 0:
        return 1
    if n % 2 == 0:
        h = potenz(x, n // 2)
        return h * h
    return x * potenz(x, n - 1)

potenz(2, 8)

def f(n, acc=1):
    if n == 0:
        return acc
    return f(n - 1, acc * 2)

print(f(5))
